package com.wayrapass.controller; import com.wayrapass.dto.request.CatalogRequests;import com.wayrapass.dto.response.CatalogResponses;import com.wayrapass.service.CatalogService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/route-schedules") @RequiredArgsConstructor public class RouteScheduleController{private final CatalogService s;@GetMapping public List<CatalogResponses.Schedule> all(){return s.schedules();}@GetMapping("/{id}") public CatalogResponses.Schedule one(@PathVariable Long id){return s.schedule(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('COORDINATOR')") public CatalogResponses.Schedule create(@Valid @RequestBody CatalogRequests.Schedule r){return s.saveSchedule(null,r);}@PutMapping("/{id}") @PreAuthorize("hasRole('COORDINATOR')") public CatalogResponses.Schedule update(@PathVariable Long id,@Valid @RequestBody CatalogRequests.Schedule r){return s.saveSchedule(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasRole('COORDINATOR')") public void delete(@PathVariable Long id){s.deleteSchedule(id);}}
